class Solution{
 public int largestPalindrome(int n){
  if(n==1)return 9;
  long base=1;for(int i=0;i<n;i++)base*=10;
  long upper=base-1,lower=base/10,gap=upper-lower;
  for(long k=2;k<=upper;k++){
   long left=base-k;if(left<lower)break;
   long x=left,right=0;while(x>0){right=right*10+x%10;x/=10;}
   long d=k*k-4L*right;if(d<0)continue;
   long r=(long)Math.sqrt((double)d);
   while((r+1)*(r+1)<=d)r++;while(r*r>d)r--;
   if(r*r!=d||((k-r)&1L)!=0)continue;
   long i=(k-r)/2,j=(k+r)/2;
   if(i>=1&&i<=gap&&j>=1&&j<=gap)return (int)((left*base+right)%1337);
  }return -1;
 }
}

