function largestPalindrome(n){
 if(n===1)return 9;
 const N=BigInt(n),base=10n**N,upper=base-1n,lower=10n**(N-1n),gap=upper-lower;
 const rev=x=>BigInt(x.toString().split("").reverse().join(""));
 for(let k=2n;k<=upper;k++){
  const left=base-k;if(left<lower)break;
  const right=rev(left),d=k*k-4n*right;if(d<0n)continue;
  let r=BigInt(Math.floor(Math.sqrt(Number(d))));
  while((r+1n)*(r+1n)<=d)r++;while(r*r>d)r--;
  if(r*r!==d||((k-r)&1n)!==0n)continue;
  const i=(k-r)/2n,j=(k+r)/2n;
  if(i>=1n&&i<=gap&&j>=1n&&j<=gap)return Number((left*base+right)%1337n);
 }
 return -1;
}
